class Box {
    private readonly int stored;
    public int Number { get => stored; init { stored = value * 2; } }
    public int Copy { get; init; }
    public int Combined { init { Number = value; Copy = Number + 1; } }
    public Box(int n = 1) { Number = n; Copy = 3; }
}
void Main() {
    var a = new Box(4); Print(a.Number); Print(a.Copy);
    var b = new Box { Combined = 5 }; Print(b.Number); Print(b.Copy);
}
